files.content:
:root {
  --header-bg-color: var(--violet, #5f0dee);
  --header-text-color: var(--white, #fff);
  --hero-bg-color: var(--black, #000);
  --hero-text-color: var(--black, #000);
  --button-bg-color: var(--fuchsia, #fd24af);
  --button-text-color: var(--white, #fff);
  --hero-title-bg-color: var(--violet, #5f0dee);
  --hero-title-text-color: var(--white, #fff);
  --description-bg-color: var(--blue, #6dc1fd);
  --description-text-color: var(--black, #000);
  --review-bg-color: var(--pink, #feafe8);
  --review-text-color: var(--black, #000);
  --links-bg-color: var(--blue, #6dc1fd);
  --links-text-color: var(--black, #000);
  --footer-bg-color: var(--violet, #5f0dee);
  --footer-text-color: var(--white, #fff);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  min-block-size: 100dvb;
  margin: 0;
  font-family: var(--main-font, 'PT Sans'), sans-serif;
  font-size: var(--main-text-size, 18px);
}

h1,
h2,
h3,
h4,
h5,
h6,
p,
ul,
li {
  margin: 0;
  padding: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

ul {
  list-style: none;
}

.header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  padding-inline: 40px;
  padding-block: 20px;
  color: var(--header-text-color);
  background-color: var(--header-bg-color);
}

.logo {
  font-weight: var(--bold-font-weight, 800);
  font-size: var(--h3-size, 31px);
  text-transform: uppercase;
  pointer-events: none;
}

.menu__list {
  display: flex;
  gap: 20px;
  font-size: 20px;
}

.hero {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-block-size: calc(100dvb - 60px);
  padding: 40px;
  box-shadow: 0 5px 10px var(--hero-bg-color);
  background-color: var(--hero-bg-color);
  background-image: url(../svg/github.svg);
  background-position: center;
  background-size: cover;
}

.hero__title {
  position: relative;
  z-index: 1;
  inline-size: fit-content;
  margin-block-end: var(--h1-margin, 30px);
  border: 1px solid currentColor;
  padding: 20px;
  color: var(--hero-title-text-color);
  font-size: var(--h1-size, 45px);
  line-height: 1;
  text-transform: uppercase;
  background-color: var(--hero-title-bg-color);
}

.button {
  inline-size: fit-content;
  border: 1px solid currentColor;
  padding-inline: 65px;
  padding-block: 10px;
  color: var(--button-text-color);
  font-family: inherit;
  font-weight: var(--bold-font-weight, 800);
  font-size: inherit;
  text-transform: uppercase;
  background-color: var(--button-bg-color);
}

.hero__link {
  position: relative;
  z-index: 1;
}

.button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  text-decoration: none;
  cursor: pointer;
}

.button:focus {
  outline: 2px solid currentColor;
  outline-offset: 0;
}

.description {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-block-size: 30dvi;
  padding: 40px;
  color: var(--description-text-color);
  background-color: var(--description-bg-color);
}

.content__title {
  max-inline-size: 600px;
  margin-block-end: var(--h2-margin, 31px);
  font-size: var(--h2-size, 38px);
  text-transform: uppercase;
}

.review {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 40px;
  padding: 40px;
  color: var(--review-text-color);
  background-color: var(--review-bg-color);
}

.review__image {
  flex-basis: 200px;
  inline-size: 200px;
}

.review__title {
  margin-block-end: var(--h3-margin, 31px);
  font-size: var(--h3-size, 31px);
  text-transform: uppercase;
}

.review__text-block {
  flex-grow: 1;
  flex-basis: 600px;
}

.links {
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding-inline: 40px;
  padding-block: 80px;
  color: var(--links-text-color);
  background-color: var(--links-bg-color);
}

.links__title {
  max-inline-size: 600px;
  margin-block-end: var(--h3-margin, 31px);
  font-size: var(--h3-size, 31px);
  text-transform: uppercase;
}

.footer {
  padding-inline: 40px;
  padding-block: 20px;
  color: var(--footer-text-color);
  background-color: var(--footer-bg-color);
}

.footer__accent {
  font-weight: var(--bold-font-weight, 800);
}
